SELECT 
FROM TBL_PAYABLE_BILL b
LEFT JOIN TBL_SUPPLIER s ON b.SUPPLIER_ID = s.SUPPLIER_ID
WHERE b.IS_DELETED = 0

    AND b.BILL_NO LIKE '%' || #{param.billNo} || '%'


    AND b.BILL_TYPE = #{param.billType}


    AND b.SUPPLIER_ID = #{param.supplierId}


    AND s.SUPPLIER_NAME LIKE '%' || #{param.supplierName} || '%'


    AND b.STATUS = #{param.status}


    AND b.ISSUE_DATE >= #{param.issueDateStart}


    AND b.ISSUE_DATE <= #{param.issueDateEnd}


    AND b.DUE_DATE >= #{param.dueDateStart}


    AND b.DUE_DATE <= #{param.dueDateEnd}


    AND b.AMOUNT >= #{param.minAmount}


    AND b.AMOUNT <= #{param.maxAmount}


    AND b.BANK_NAME LIKE '%' || #{param.bankName} || '%'


    AND (b.BILL_NO LIKE '%' || #{param.keyword} || '%'
         OR s.SUPPLIER_NAME LIKE '%' || #{param.keyword} || '%')

ORDER BY b.CREATE_TIME DESC

SELECT FROM TBL_PAYABLE_BILL b LEFT JOIN TBL_SUPPLIER s ON b.SUPPLIER_ID = s.SUPPLIER_ID WHERE b.IS_DELETED = 0
AND b.STATUS IN ('active', 'due') AND b.DUE_DATE <= TRUNC(SYSDATE)
AND b.STATUS = 'active' AND b.DUE_DATE BETWEEN TRUNC(SYSDATE) AND TRUNC(SYSDATE) + #{days}
AND b.BILL_TYPE = #{billType}
ORDER BY b.DUE_DATE ASC
